export function nextGeneration(liveCells: Cell[]): Cell[] {
  const live = new Set(liveCells.map(toKey));

  const neighborCounts = new Map<string, number>();
  for (const [x, y] of liveCells) {
    for (const [nx, ny] of neighborsOf([x, y])) {
      const key = toKey([nx, ny]);
      neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
    }
  }

  const survivors: Cell[] = [];
  for (const [key, count] of neighborCounts) {
    if (count === 3 || (count === 2 && live.has(key))) {
      survivors.push(fromKey(key));
    }
  }
  return survivors;
}

function neighborsOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => dx !== 0 || dy !== 0)
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

const toKey = ([x, y]: Cell): string => `${x},${y}`;

const fromKey = (key: string): Cell => {
  const [x, y] = key.split(",").map(Number);
  return [x, y];
};

